xql_query:
// ============================================================
// Rule: FTG_High Memory Usage
// Vendor: Fortigate
// Objective:
// Detect activity associated with FTG_High Memory Usage.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0040 - Impact
// Technique: T1498 - Network Denial of Service

// Fonte de dados: logs brutos do Fortinet FortiGate
dataset = fortinet_fortigate_raw  

// Filtra apenas mensagens que contenham a palavra "memory"
| filter msg contains "memory"  

// Converte o valor de utilização de memória (FTNTFGTmem) para inteiro
| alter memoria = to_integer(FTNTFGTmem)  

// Calcula a média de uso de memória por dispositivo reportado
| comp avg(memoria) as memoria by _reporting_device_name  

// Mantém apenas os casos em que a média de memória ultrapassa 74%
| filter memoria > 74
